describe('Dashboard Sidebar Responsiveness', () => {
    beforeEach(() => {
        cy.visit('/dashboard');
        cy.viewport('iphone-6'); // Simulate mobile viewport
    });

    it('should display the bottom nav bar on mobile', () => {
        cy.get('.sidebar').should('not.exist'); // Sidebar should not be visible
        cy.get('.bottom-nav').should('be.visible'); // Bottom nav bar should be visible
    });

    it('should navigate to the correct page when bottom nav items are clicked', () => {
        cy.get('.bottom-nav .nav-item').first().click(); // Click the first nav item
        cy.url().should('include', '/first-page'); // Verify URL changes to first page

        cy.get('.bottom-nav .nav-item').eq(1).click(); // Click the second nav item
        cy.url().should('include', '/second-page'); // Verify URL changes to second page
    });
});
